--
-- Name: cosine_similarity(real[], real[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cosine_similarity(vec1 real[], vec2 real[]) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    AS $$
declare
    dot float := 0;
    norm1 float := 0;
    norm2 float := 0;
    i int;
begin
    for i in array_lower(vec1,1)..array_upper(vec1,1) loop
        dot := dot + vec1[i]*vec2[i];
        norm1 := norm1 + vec1[i]*vec1[i];
        norm2 := norm2 + vec2[i]*vec2[i];
    end loop;
    
    if norm1 = 0 or norm2 = 0 then
        return 0;
    end if;

    return dot / (sqrt(norm1) * sqrt(norm2));
end;
$$;


--
-- Name: generate_embedding(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_embedding(input_text text) RETURNS public.vector
    LANGUAGE plpgsql
    AS $$
declare
  embedding vector(768);
begin
  select
    genai.embedding(
      'models/embedding-001',
      input_text
    )::vector(768)
  into embedding;

  return embedding;
end;
$$;


