--
-- Name: match_course_embeddings(real[], integer, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_course_embeddings(query_embedding real[], match_count integer, similarity_threshold double precision) RETURNS TABLE(id bigint, name text, description text, tags text[], similarity double precision)
    LANGUAGE plpgsql
    AS $$
begin
    return query
    select
        c.id,
        c.name,
        c.description,
        c.tags,
        cosine_similarity(c.embedding, query_embedding) as similarity
    from public.course_embeddings c
    where cosine_similarity(c.embedding, query_embedding) >= similarity_threshold
    order by similarity desc
    limit match_count;
end;
$$;


--
-- Name: match_course_embeddings(public.vector, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_course_embeddings(query_embedding public.vector, match_count integer, filter jsonb DEFAULT '{}'::jsonb) RETURNS TABLE(id character varying, name text, description text, tags text[], link text, content text, metadata jsonb, similarity double precision)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    c.id,
    c.name,
    c.description,
    c.tags,
    c.link,
    c.content,
    c.metadata,
    1 - (c.embedding <=> query_embedding) AS similarity
  FROM course_embeddings c
  WHERE c.metadata @> filter
  ORDER BY c.embedding <=> query_embedding
  LIMIT match_count;
END;
$$;


